From bc7f6b5ef70e49372d43087bf6ab98b8ebbd494a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:54:33 +0100
Subject: [PATCH] applets/kickoff: focus the search field when opening

Compose keys and input methods only work in a focused text field, so the
first accented letter typed after opening Kickoff lost its accent. The
field now takes focus and passes navigation keys to the content area.

BUG: 459269
---
 applets/kickoff/BasePage.qml        | 11 ++++++++++
 applets/kickoff/Header.qml          | 32 ++++++++++++++++++++++++-----
 applets/kickoff/KickoffGridView.qml |  4 ++--
 applets/kickoff/main.qml            |  2 ++
 4 files changed, 42 insertions(+), 7 deletions(-)

diff --git a/applets/kickoff/BasePage.qml b/applets/kickoff/BasePage.qml
index d214947ba4..f52c24e7d0 100644
--- a/applets/kickoff/BasePage.qml
+++ b/applets/kickoff/BasePage.qml
@@ -137,6 +137,10 @@ FocusScope {
                     sideBarLoader.forceActiveFocus();
                 } break
                 case Qt.Key_Up:
+                    // Right after opening, the search field has focus and forwards keys here
+                    if (kickoff.searchField.activeFocus) {
+                        return;
+                    }
                     kickoff.searchField.forceActiveFocus(Qt.BacktabFocusReason);
                     break
                 case Qt.Key_Down:
@@ -149,4 +153,11 @@ FocusScope {
             event.accepted = true;
         }
     }
+    Binding {
+        target: kickoff
+        property: "contentAreaPane"
+        value: contentAreaLoader
+        when: root.T.StackView.status === T.StackView.Active && root.visible
+        restoreMode: Binding.RestoreBinding
+    }
 }
diff --git a/applets/kickoff/Header.qml b/applets/kickoff/Header.qml
index 611d247d76..2cfa9503e1 100644
--- a/applets/kickoff/Header.qml
+++ b/applets/kickoff/Header.qml
@@ -197,6 +197,10 @@ PlasmaExtras.PlasmoidHeading {
                     Layout.leftMargin: kickoff.backgroundMetrics.leftPadding
                     focus: true

+                    // Focused by opening Kickoff: navigation keys still act on the
+                    // content area until the user types or moves focus elsewhere
+                    property bool focusedOnOpen: false
+
                     Binding {
                         target: kickoff
                         property: "searchField"
@@ -209,22 +213,40 @@ PlasmaExtras.PlasmoidHeading {
                         function onExpandedChanged() {
                             if (!kickoff.expanded) {
                                 searchField.clear()
+                            } else {
+                                // Input methods and compose/dead keys only work in a focused text field
+                                searchField.forceActiveFocus(Qt.OtherFocusReason)
+                                searchField.focusedOnOpen = true
                             }
                         }
                     }
+                    onActiveFocusChanged: {
+                        if (!activeFocus) {
+                            focusedOnOpen = false
+                        }
+                    }
+                    onPressed: focusedOnOpen = false
                     onTextEdited: {
+                        focusedOnOpen = false
                         searchField.forceActiveFocus(Qt.ShortcutFocusReason)
                     }
-                    Keys.priority: Keys.AfterItem
+                    Keys.priority: focusedOnOpen ? Keys.BeforeItem : Keys.AfterItem
                     Keys.forwardTo: {
                         if (kickoff.contentArea === null) {
                             return []
                         }
+                        // The pane moves focus out of the content area, as it does on master
+                        const pane = focusedOnOpen ? [kickoff.contentAreaPane] : []
                         if (kickoff.contentArea instanceof ListOfGridsView) {
                             // forward to grid inside of list, or down will skip the whole grid'
-                            return [kickoff.contentArea.view.currentItem?.view, kickoff.contentArea.view]
+                            return [kickoff.contentArea.view.currentItem?.view, kickoff.contentArea.view, ...pane]
                         }
-                        return kickoff.contentArea.view
+                        return [kickoff.contentArea.view, ...pane]
+                    }
+                    // Up from the top of the content area would focus the search field
+                    Keys.onUpPressed: event => {
+                        focusedOnOpen = false
+                        event.accepted = false
                     }

                     Keys.onTabPressed: event => {
@@ -236,11 +258,11 @@ PlasmaExtras.PlasmoidHeading {
                     // Handles both the arrow keys and Ctrl+H/J/K/L
                     Keys.onPressed: event => {
                         switch (KickoffSingleton.navigationKey(event)) {
-                            case Qt.Key_Left: if (activeFocus) {
+                            case Qt.Key_Left: if (activeFocus && !focusedOnOpen) {
                                 (sideBarOnRight ? configureButton : avatar).forceActiveFocus(
                                     Application.layoutDirection === Qt.RightToLeft ? Qt.TabFocusReason : Qt.BacktabFocusReason)
                             } break
-                            case Qt.Key_Right: if (activeFocus) {
+                            case Qt.Key_Right: if (activeFocus && !focusedOnOpen) {
                                 (sideBarOnRight ? avatar : configureButton).forceActiveFocus(
                                     Application.layoutDirection === Qt.RightToLeft ? Qt.BacktabFocusReason : Qt.TabFocusReason)
                             } break
diff --git a/applets/kickoff/KickoffGridView.qml b/applets/kickoff/KickoffGridView.qml
index a2f3fae9f1..9fec064793 100644
--- a/applets/kickoff/KickoffGridView.qml
+++ b/applets/kickoff/KickoffGridView.qml
@@ -238,7 +238,7 @@ EmptyPage {
                 event.accepted = true;
             } else if (count > 1) {
                 switch (KickoffSingleton.navigationKey(event)) {
-                    case Qt.Key_Left: if (!atLeft && !kickoff.searchField.activeFocus) {
+                    case Qt.Key_Left: if (!atLeft && (!kickoff.searchField.activeFocus || kickoff.searchField.focusedOnOpen)) {
                         moveCurrentIndexLeft()
                         focusCurrentItem(event, Qt.BacktabFocusReason)
                     } break
@@ -246,7 +246,7 @@ EmptyPage {
                         moveCurrentIndexUp()
                         focusCurrentItem(event, Qt.BacktabFocusReason)
                     } break
-                    case Qt.Key_Right: if (!atRight && !kickoff.searchField.activeFocus) {
+                    case Qt.Key_Right: if (!atRight && (!kickoff.searchField.activeFocus || kickoff.searchField.focusedOnOpen)) {
                         moveCurrentIndexRight()
                         focusCurrentItem(event, Qt.TabFocusReason)
                     } break
diff --git a/applets/kickoff/main.qml b/applets/kickoff/main.qml
index 6b6c95dabe..02e57f029d 100644
--- a/applets/kickoff/main.qml
+++ b/applets/kickoff/main.qml
@@ -128,6 +128,8 @@ PlasmoidItem {
     // Set in FullRepresentation.qml, ApplicationPage.qml, PlacesPage.qml
     property Item sideBar: null // is null when searching
     property Item contentArea: null // is searchView when searching
+    // Set in BasePage.qml: holds contentArea and moves focus out of it
+    property Item contentAreaPane: null

     // Set in NormalPage.qml
     property Item footer: null
-- 
